import{_ as e,c as t,ag as n,o}from"./chunks/framework.ChSLcS_6.js";const i="/assets/langsim.CONYfkEV.png",r="/assets/T2Dllama.DGG_b6xn.png",l="/assets/yeLLowhaMMer.BCNZD5hS.png",f=JSON.parse('{"title":"2024 Large Language Model (LLM) Hackathon for Applications in Materials Science and Chemistry","description":"","frontmatter":{},"headers":[],"relativePath":"StudyRec/20250217-2024LLMHackInSci.md","filePath":"StudyRec/20250217-2024LLMHackInSci.md"}'),s={name:"StudyRec/20250217-2024LLMHackInSci.md"};function c(g,a,h,m,d,u){return o(),t("div",null,a[0]||(a[0]=[n('<h1 id="_2024-large-language-model-llm-hackathon-for-applications-in-materials-science-and-chemistry" tabindex="-1"><div style="text-align:center;"><h1 style="font-size:2.5rem;font-weight:bold;">2024 Large Language Model (LLM) Hackathon for Applications in Materials Science and Chemistry</h1></div> <a class="header-anchor" href="#_2024-large-language-model-llm-hackathon-for-applications-in-materials-science-and-chemistry" aria-label="Permalink to &quot;&lt;div style=&quot;text-align: center;&quot;&gt;&lt;h1 style=&quot;font-size: 2.5rem; font-weight: bold&quot;&gt;2024 Large Language Model (LLM) Hackathon for Applications in Materials Science and Chemistry&lt;/h1&gt;&lt;/div&gt;&quot;">​</a></h1><p>偶然搜到了这个材料科学和化学应用大型语言模型 LLM 黑客马拉松。非常感兴趣遂记录之。<a href="https://github.com/bocarsly-group/llm-hackathon-2024" target="_blank" rel="noreferrer">→</a></p><h2 id="areas" tabindex="-1">Areas <a class="header-anchor" href="#areas" aria-label="Permalink to &quot;Areas&quot;">​</a></h2><ol><li><strong>Molecular and Material Property Prediction</strong>：使用LLMs预测分子和材料的化学和物理性质，尤其擅长低数据环境，并结合结构化/非结构化数据。</li><li><strong>Molecular and Material Design</strong>：使用LLMs生成和优化新型分子和材料，包括肽、金属有机框架和环保建筑材料。</li><li><strong>Automation and Novel Interfaces</strong>：开发自然语言界面和自动化工作流程，简化复杂的科学任务，使研究人员更容易使用先进的工具和技术。（这个最好玩）</li><li><strong>Scientific Communication and Education</strong>：加强学术交流，自动化教育内容创建，促进材料科学和化学的学习。</li><li><strong>Research Data Management and Automation</strong>：通过LLM驱动的工具和多模态代理简化科学数据的处理、组织和管理。（这个最感兴趣）</li><li><strong>Hypothesis Generation and Evaluation</strong>：使用LLMs生成、评估和验证科学假设，通常结合多个AI代理和统计方法。</li><li><strong>Knowledge Extraction and Reasoning</strong>：通过知识图谱和多模态方法，从科学文献中提取结构化信息，并对化学和材料科学概念进行深入推理。（这个相对来说很成熟了）</li></ol><h2 id="自动化工作流程" tabindex="-1">自动化工作流程 <a class="header-anchor" href="#自动化工作流程" aria-label="Permalink to &quot;自动化工作流程&quot;">​</a></h2><h3 id="langsim→" tabindex="-1">LangSim<a href="http://jan-janssen.com/LangSim/" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#langsim→" aria-label="Permalink to &quot;LangSim[→](http://jan-janssen.com/LangSim/)&quot;">​</a></h3><div class="custom-image"><p><img src="'+i+'" alt="shap_interaction_matrix"></p></div><p>LangSim 研究代理基于 LangChain 包构建，将现有仿真工作流实现为 LangChain 代理。</p><p>虽然我觉得这个软件优点很多，但是LLM 很难自主解决很多模拟上的问题。感觉软件计算几种简单的的性质还好，</p><h3 id="t2dllama-harnessing-language-model-for-density-functional-theory-dft-parameter-suggestion→" tabindex="-1">T2Dllama: Harnessing Language Model for Density Functional Theory (DFT) Parameter Suggestion<a href="https://github.com/chiku-parida/T2Dllama" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#t2dllama-harnessing-language-model-for-density-functional-theory-dft-parameter-suggestion→" aria-label="Permalink to &quot;T2Dllama: Harnessing Language Model for Density Functional Theory (DFT) Parameter Suggestion[→](https://github.com/chiku-parida/T2Dllama)&quot;">​</a></h3><div class="custom-image"><p><img src="'+r+'" alt="shap_interaction_matrix"></p></div><p>这个呢是利用了 retrieval augmented generation (RAG) technique <sup class="footnote-ref"><a href="#RAG" id="RAG">[1]</a></sup> 相当于接入了数据库（虽然有研究表明这个不如上下文长一点把材料都丢里面效果好）。</p><h3 id="yellowhammer-a-multi-modal-tool-calling-agent-for-accelerated-research-data-management→" tabindex="-1">yeLLowhaMMer: A Multi-modal Tool-calling Agent for Accelerated Research Data Management<a href="https://github.com/datalab-org/yellowhammer" target="_blank" rel="noreferrer">→</a> <a class="header-anchor" href="#yellowhammer-a-multi-modal-tool-calling-agent-for-accelerated-research-data-management→" aria-label="Permalink to &quot;yeLLowhaMMer: A Multi-modal Tool-calling Agent for Accelerated Research Data Management[→](https://github.com/datalab-org/yellowhammer)&quot;">​</a></h3><p>使用 LLMs 来简化和加速数据处理任务，从用户那里获取自由格式的文本和图像指令并执行各种复杂的科学数据管理任务。</p><div class="custom-image"><p><img src="'+l+'" alt="shap_interaction_matrix"></p></div><p>例如指示代理：“提取我最近的 10 个示例条目，并总结所使用的合成方法。在这种情况下，代理将尝试使用 datalab API 编写和执行 Python 代码，以在 datalab 实例中查询用户的样本并编写人类可读的摘要。如果它生成的代码给出错误（或没有提供足够的信息），代理可以迭代重写程序，直到任务成功完成。</p><section class="footnotes"><ol class="footnotes-list"><li id="RAG" class="footnote-item"><p> Yunfan Gao, Yun Xiong, Xinyu Gao, Kangxiang Jia, Jinliu Pan, Yuxi Bic, Yi Dai, Jiawei Sun, Meng Wang, and Haofen Wang, “Retrieval-Augmented Generation for Large Language Models: A Survey”, <a href="https://doi.org/10.48550/arXiv.2312.10997" target="_blank">https://doi.org/10.48550/arXiv.2312.10997</a>. <a href="#fnRAG" class="footnote-backref">↩</a></p></li></ol></section>',17)]))}const L=e(s,[["render",c]]);export{f as __pageData,L as default};
